<?php
declare(strict_types=1);
const CRM_SCHEMA_VERSION=1;
function crmSchemaSteps(): array {
 $tables=[
 'rubizh_staff_roles'=>"role VARCHAR(16) PRIMARY KEY,label VARCHAR(80) NOT NULL",
 'rubizh_staff_permissions'=>"role VARCHAR(16) NOT NULL,permission VARCHAR(64) NOT NULL,PRIMARY KEY(role,permission)",
 'rubizh_staff_users'=>"id CHAR(32) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(16) NOT NULL,enabled TINYINT NOT NULL DEFAULT 1,session_version INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(role,enabled)",
 'rubizh_order_assignments'=>"order_id BIGINT UNSIGNED PRIMARY KEY,staff_id CHAR(32) NULL,assigned_by CHAR(32) NOT NULL,updated_at DATETIME NOT NULL,INDEX(staff_id,order_id)",
 'rubizh_internal_notes'=>"id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity VARCHAR(16) NOT NULL,entity_id VARCHAR(254) NOT NULL,author_id CHAR(32) NOT NULL,body TEXT NOT NULL,request_id CHAR(32) NOT NULL UNIQUE,created_at DATETIME NOT NULL,INDEX(entity,entity_id,id)",
 'rubizh_staff_audit'=>"id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id CHAR(32) NOT NULL,actor_role VARCHAR(16) NOT NULL,source VARCHAR(24) NOT NULL,entity VARCHAR(24) NOT NULL,entity_id VARCHAR(254) NOT NULL,action VARCHAR(80) NOT NULL,before_json JSON NOT NULL,after_json JSON NOT NULL,reason VARCHAR(400) NOT NULL,request_id CHAR(32) NOT NULL,created_at DATETIME NOT NULL,INDEX(entity,entity_id,id),INDEX(created_at,id),INDEX(actor_id,id)",
 'rubizh_returns'=>"id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,state VARCHAR(24) NOT NULL,lines_json JSON NOT NULL,reason VARCHAR(400) NOT NULL,tracking_number VARCHAR(14) NOT NULL DEFAULT '',refund_expected_minor BIGINT UNSIGNED NOT NULL,refund_allocations_json JSON NULL,inventory_decision VARCHAR(32) NOT NULL DEFAULT 'PENDING',inventory_evidence VARCHAR(400) NOT NULL DEFAULT '',created_by CHAR(32) NOT NULL,request_id CHAR(32) NOT NULL UNIQUE,version INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(order_id,id),INDEX(state,updated_at)",
 'rubizh_refund_operations'=>"id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,amount BIGINT UNSIGNED NOT NULL,ext_ref VARCHAR(100) NOT NULL UNIQUE,status VARCHAR(24) NOT NULL,reason VARCHAR(400) NOT NULL,actor_id CHAR(32) NOT NULL,idempotency_key CHAR(32) NOT NULL UNIQUE,response_json JSON NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(order_id,status,id),INDEX(invoice_id,status)",
 'rubizh_sender_profiles'=>"code VARCHAR(32) PRIMARY KEY,name VARCHAR(120) NOT NULL,city VARCHAR(120) NOT NULL,region VARCHAR(120) NOT NULL,branch VARCHAR(20) NOT NULL,cargo_branch VARCHAR(20) NOT NULL DEFAULT '',city_ref VARCHAR(36) NOT NULL DEFAULT '',warehouse_ref VARCHAR(36) NOT NULL DEFAULT '',cargo_warehouse_ref VARCHAR(36) NOT NULL DEFAULT '',sender_ref VARCHAR(36) NOT NULL DEFAULT '',contact_ref VARCHAR(36) NOT NULL DEFAULT '',phone VARCHAR(20) NOT NULL DEFAULT '',confirmed TINYINT NOT NULL DEFAULT 0,version INT UNSIGNED NOT NULL DEFAULT 1,updated_by CHAR(32) NOT NULL,updated_at DATETIME NOT NULL",
 'rubizh_order_contact_evidence'=>"order_id BIGINT UNSIGNED PRIMARY KEY,raw_phone VARCHAR(80) NOT NULL,normalized_phone VARCHAR(20) NULL,evidence VARCHAR(24) NOT NULL DEFAULT 'ORDER_CONTACT',updated_at DATETIME NOT NULL,INDEX(normalized_phone,order_id)",
 'rubizh_crm_migrations'=>"step VARCHAR(100) PRIMARY KEY,sql_hash CHAR(64) NOT NULL,object_hash CHAR(64) NOT NULL,applied_at DATETIME NOT NULL",
 ];$out=[];foreach($tables as $name=>$body)$out[]=['kind'=>'table','name'=>$name,'sql'=>"CREATE TABLE $name($body) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"];
 foreach(['rubizh_staff_audit','rubizh_internal_notes'] as $t)foreach(['UPDATE','DELETE'] as $v){$name=$t.'_no_'.strtolower($v);$out[]=['kind'=>'trigger','name'=>$name,'sql'=>"CREATE TRIGGER $name BEFORE $v ON $t FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CRM history is append-only'"];}
 foreach(['crm_order_created'=>['rubizh_customer_orders','created_at,id'],'crm_order_payment_queue'=>['rubizh_customer_orders','payment_status,status,created_at,id'],'crm_order_confirmation_queue'=>['rubizh_customer_orders','pim_order_state,created_at,id'],'crm_shipment_status'=>['rubizh_order_shipments','status,updated_at,id'],'crm_mono_event_paid'=>['rubizh_mono_events','status,invoice_id,created_at']] as $name=>[$table,$columns])$out[]=['kind'=>'index','name'=>$name,'table'=>$table,'sql'=>"CREATE INDEX $name ON $table($columns)"];
 return $out;
}
function crmSchemaReady(PDO $db): bool {return (int)$db->query("SELECT v FROM meta WHERE k='crm_schema'")->fetchColumn()===CRM_SCHEMA_VERSION;}
function crmMigrate(PDO $db): void {
 if(PHP_SAPI!=='cli'||$db->inTransaction())throw new RuntimeException('CLI migration only');
 if(crmStepExists($db,['kind'=>'table','name'=>'rubizh_crm_migrations']))foreach(crmSchemaSteps() as $s){$q=$db->prepare("SELECT CONCAT(sql_hash,':',object_hash) FROM rubizh_crm_migrations WHERE step=?");$q->execute([$s['name']]);$old=$q->fetchColumn();if($old!==false&&(!hash_equals(explode(':',$old)[0],hash('sha256',$s['sql']))||crmStepExists($db,$s)&&!hash_equals(explode(':',$old)[1],crmObjectHash($db,$s))||!crmStepExists($db,$s)))throw new RuntimeException('CRM migration drift');}
 $journal=crmStepExists($db,['kind'=>'table','name'=>'rubizh_crm_migrations']);if(!$journal)foreach(crmSchemaSteps() as $s)if(crmStepExists($db,$s))throw new RuntimeException('Unjournaled CRM schema collision');
 $steps=crmSchemaSteps();foreach($steps as $s)if($s['name']==='rubizh_crm_migrations'&&!$journal)$db->exec($s['sql']);
 foreach($steps as $s){$hash=hash('sha256',$s['sql']);$q=$db->prepare('SELECT sql_hash,object_hash FROM rubizh_crm_migrations WHERE step=?');$q->execute([$s['name']]);$old=$q->fetch(PDO::FETCH_ASSOC);if($old){if(!hash_equals($old['sql_hash'],$hash)||!crmStepExists($db,$s)||!hash_equals($old['object_hash'],crmObjectHash($db,$s)))throw new RuntimeException('CRM migration drift');continue;}if(crmStepExists($db,$s)&&$s['name']!=='rubizh_crm_migrations')throw new RuntimeException('Unjournaled CRM object');if(!crmStepExists($db,$s))$db->exec($s['sql']);$db->prepare('INSERT INTO rubizh_crm_migrations(step,sql_hash,object_hash,applied_at) VALUES(?,?,?,UTC_TIMESTAMP())')->execute([$s['name'],$hash,crmObjectHash($db,$s)]);}
 $db->beginTransaction();try{
 foreach(['OWNER'=>'Власник','MANAGER'=>'Менеджер','LOGISTICS'=>'Логістика','READ_ONLY'=>'Перегляд'] as $role=>$label){$db->prepare('INSERT IGNORE INTO rubizh_staff_roles(role,label) VALUES(?,?)')->execute([$role,$label]);foreach(crmRolePermissions($role) as $permission)$db->prepare('INSERT IGNORE INTO rubizh_staff_permissions(role,permission) VALUES(?,?)')->execute([$role,$permission]);}
 foreach(npOrigins() as $code=>$o){$s=cfg('np_sender')??[];$db->prepare('INSERT IGNORE INTO rubizh_sender_profiles(code,name,city,region,branch,cargo_branch,city_ref,warehouse_ref,cargo_warehouse_ref,sender_ref,contact_ref,phone,confirmed,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP())')->execute([$code,$o['name'],$o['city'],$o['region'],$o['branch'],$o['cargo_branch']??'',$o['city_ref']??'',$o['warehouse_ref']??'',$o['cargo_warehouse_ref']??'',$s['ref']??'',$s['contact_ref']??'',$s['phone']??'',!empty($o['confirmed'])&&!empty($s['confirmed'])?1:0,str_repeat('0',32)]);}
 $db->exec("INSERT INTO meta(k,v) VALUES('crm_schema','1') ON DUPLICATE KEY UPDATE v=VALUES(v)");$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}
}

function crmStepExists(PDO $db,array $s): bool {if($s['kind']!=='index')return shopP0StepExists($db,$s);$q=$db->prepare('SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND INDEX_NAME=?');$q->execute([$s['table'],$s['name']]);return (bool)$q->fetchColumn();}
function crmObjectHash(PDO $db,array $s): string {if($s['kind']==='table'){$v=$db->query('SHOW CREATE TABLE `'.$s['name'].'`')->fetch(PDO::FETCH_NUM)[1];$v=preg_replace('/ AUTO_INCREMENT=\d+/','',$v);}elseif($s['kind']==='trigger'){$q=$db->prepare('SELECT EVENT_MANIPULATION,EVENT_OBJECT_TABLE,ACTION_STATEMENT,ACTION_TIMING FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME=?');$q->execute([$s['name']]);$v=json_encode($q->fetch(PDO::FETCH_ASSOC),JSON_THROW_ON_ERROR);}else{$q=$db->prepare('SELECT NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME,SUB_PART,INDEX_TYPE FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND INDEX_NAME=? ORDER BY SEQ_IN_INDEX');$q->execute([$s['table'],$s['name']]);$v=json_encode($q->fetchAll(PDO::FETCH_ASSOC),JSON_THROW_ON_ERROR);}return hash('sha256',$v);}
